// @vitest-environment jsdom
/**
 * Guards the home page example (public/samples/etang-ayguelongue-pic-de-l-homme.gpx, a real hike) and the fixture of
 * the tests (src/import/__fixtures__/tour-du-mont-blanc-j1.gpx, generated by scripts/gen-sample-gpx.mjs): both must
 * stay parseable and realistic.
 */
import { describe, expect, it } from 'vitest'
import exampleGpx from '../../public/samples/etang-ayguelongue-pic-de-l-homme.gpx?raw'
import sampleGpx from './__fixtures__/tour-du-mont-blanc-j1.gpx?raw'
import { parseGpx } from './gpx'

describe('home page example etang-ayguelongue-pic-de-l-homme.gpx', () => {
  const tracks = parseGpx(exampleGpx, 'etang-ayguelongue-pic-de-l-homme.gpx')

  it('is one light, timed hike in the Pyrenees, with its heart rate', () => {
    expect(exampleGpx.length).toBeLessThan(600_000)
    expect(tracks).toHaveLength(1)
    const track = tracks[0]
    expect(track.name).toBe('Étang d’Ayguelongue et pic de l’homme')
    const points = track.segments[0].points
    expect(points.length).toBeGreaterThan(1500)
    expect(points.length).toBeLessThan(3000)
    expect(points[0].lat).toBeCloseTo(42.676, 2)
    expect(points[0].lon).toBeCloseTo(1.871, 2)
    expect(track.stats.distanceM).toBeGreaterThan(10_000)
    expect(track.stats.ascentM).toBeGreaterThan(500)
    expect(track.stats.startTime).toBe(Date.parse('2026-08-02T09:30:13Z'))
    expect(track.stats.durationS).toBeGreaterThan(6 * 3600)
    for (let i = 1; i < points.length; i++) expect(points[i].time!).toBeGreaterThan(points[i - 1].time!)
    expect(points.every((p) => typeof p.hr === 'number')).toBe(true)
  })
})

describe('sample tour-du-mont-blanc-j1.gpx', () => {
  const tracks = parseGpx(sampleGpx, 'tour-du-mont-blanc-j1.gpx')

  it('is a single realistic track from Les Houches to Les Contamines', () => {
    expect(tracks).toHaveLength(1)
    const track = tracks[0]
    expect(track.name).toMatch(/Mont-Blanc/)
    expect(track.segments).toHaveLength(1)
    const points = track.segments[0].points

    expect(points.length).toBeGreaterThanOrEqual(300)
    expect(points.length).toBeLessThanOrEqual(420)
    expect(points[0].lon).toBeCloseTo(6.7986, 2)
    expect(points[0].lat).toBeCloseTo(45.8911, 2)
    expect(points[points.length - 1].lon).toBeCloseTo(6.7273, 2)
    expect(points[points.length - 1].lat).toBeCloseTo(45.8225, 2)

    expect(track.stats.distanceM).toBeGreaterThan(15_000)
    expect(track.stats.distanceM).toBeLessThan(18_000)
    expect(track.stats.ascentM).toBeGreaterThan(650)
    expect(track.stats.ascentM).toBeLessThan(1000)
    expect(track.stats.descentM).toBeGreaterThan(450)
    expect(track.stats.minEle).toBeGreaterThan(950)
    expect(track.stats.maxEle).toBeGreaterThan(1640)
    expect(track.stats.maxEle).toBeLessThan(1700)
    expect(track.stats.startTime).toBe(Date.parse('2025-07-12T07:00:00Z'))
    expect(track.stats.durationS).toBeGreaterThan(4 * 3600)
    expect(track.stats.durationS).toBeLessThan(7 * 3600)
  })

  it('has monotonic times every ~60 s and a heart rate on every point', () => {
    const points = tracks[0].segments[0].points
    for (let i = 1; i < points.length; i++) {
      expect(points[i].time! - points[i - 1].time!).toBe(60_000)
    }
    for (const p of points) {
      expect(p.hr).toBeGreaterThanOrEqual(90)
      expect(p.hr).toBeLessThanOrEqual(150)
      expect(p.ele).toBeDefined()
    }
  })
})
